from typing import List

def negabinary_encode(n: int) -> List[int]:
    """Canonical base-(-2) digits of n, least-significant first."""
    digits: List[int] = []
    while n != 0:
        b = n % 2
        digits.append(b)
        n = (n - b) // (-2)
    return digits

def negabinary_decode(digits: List[int]) -> int:
    return sum(b * ((-2) ** i) for i, b in enumerate(digits))

def negabinary_string(n: int) -> str:
    d = negabinary_encode(n)
    return "".join(str(b) for b in reversed(d)) if d else "0"

if __name__ == "__main__":
    seen = {}
    for n in range(-20, 21):
        s = negabinary_string(n)
        assert negabinary_decode(negabinary_encode(n)) == n
        assert s not in seen, "collision!"
        seen[s] = n
        print(f"{n:>4} = {s:>8}(-2)")
    print("Every integer in [-20, 20] has a unique, sign-free representation.")

from typing import Tuple
from math import sqrt

PHI = (1.0 + sqrt(5.0)) / 2.0
PSI = (1.0 - sqrt(5.0)) / 2.0

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def carry(n: int) -> Tuple[float, float]:
    """Verify phi^n + phi^(n+1) = phi^(n+2)."""
    return (PHI ** n + PHI ** (n + 1), PHI ** (n + 2))

def lucas_identity(n: int) -> Tuple[float, int]:
    """Verify phi^(n+1) + psi^(n+1) = F_{n+2} + F_n."""
    return (PHI ** (n + 1) + PSI ** (n + 1), fib(n + 2) + fib(n))

if __name__ == "__main__":
    for n in range(7):
        lhs, rhs = carry(n)
        print(f"carry n={n}: {lhs:.8f} == {rhs:.8f}")
    print(f"3 = phi^2 + phi^-2 = {PHI**2 + PHI**-2:.10f}")
    for n in range(7):
        lhs, rhs = lucas_identity(n)
        print(f"Lucas n={n}: {lhs:.6f} ~= {rhs}")

from typing import List

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def zeckendorf(n: int) -> List[int]:
    """Return Fibonacci indices (>=2, no two consecutive) summing to n."""
    if n <= 0:
        return []
    ks: List[int] = []
    k = 2
    while fib(k) <= n:
        k += 1
    for j in range(k - 1, 1, -1):
        if fib(j) <= n:
            ks.append(j)
            n -= fib(j)
    return ks

def no_consecutive(ks: List[int]) -> bool:
    s = sorted(ks)
    return all(s[i + 1] - s[i] >= 2 for i in range(len(s) - 1))

if __name__ == "__main__":
    for n in range(1, 26):
        ks = zeckendorf(n)
        assert sum(fib(k) for k in ks) == n and no_consecutive(ks)
        terms = " + ".join(f"F_{k}" for k in sorted(ks, reverse=True))
        print(f"{n:>3} = {terms:<24} no-adjacent: {no_consecutive(ks)}")

