function NEGABINARY-ENCODE(n):
    digits <- empty list
    while n != 0:
        b <- n mod 2            # nonnegative remainder in {0,1}
        append b to digits
        n <- (n - b) / (-2)     # exact integer division
    return digits               # least-significant digit first

function MU(n):
    if n >= 0:
        return 2*n
    else:
        return -2*n - 1

# Guarantee: for n != 0, MU((n - n mod 2)/(-2)) < MU(n).

function ZECKENDORF(n):
    build Fibonacci list F with F[-1] > n
    chosen <- empty list
    idx <- top index of F
    while n > 0 and idx >= 0:
        if F[idx] <= n:
            append (idx+2) to chosen   # F_2 = 1, F_3 = 2, ...
            n <- n - F[idx]
            idx <- idx - 2             # skip neighbor (no adjacency)
        else:
            idx <- idx - 1
    return chosen
